import type { MetadataRoute } from "next"

// Icons are generated by scripts/generate-icons.mjs.
const sizes = [48, 64, 96, 128, 144, 192, 256, 384, 512]

export default function manifest(): MetadataRoute.Manifest {
  return {
    name: "Mini Food",
    short_name: "Mini Food",
    description: "Order food from your favourite restaurants.",
    start_url: "/",
    display: "standalone",
    background_color: "#ffffff",
    theme_color: "#ea580c",
    icons: [
      { src: "/icons/icon.svg", sizes: "any", type: "image/svg+xml" },
      ...sizes.map((size) => ({
        src: `/icons/icon-${size}.png`,
        sizes: `${size}x${size}`,
        type: "image/png",
      })),
      ...[192, 512].map((size) => ({
        src: `/icons/icon-maskable-${size}.png`,
        sizes: `${size}x${size}`,
        type: "image/png",
        purpose: "maskable" as const,
      })),
    ],
  }
}
